import{_ as o,a0 as r,w as d,s as p,ao as l,I as i,x as e,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在 Fedora 命令列下玩轉防火牆 | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora 命令列下玩轉防火牆 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora 命令列下玩轉防火牆 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora 命令列下玩轉防火牆 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200320 Control the firewall at the command line","title":"在 Fedora 命令列下玩轉防火牆","tag":"202004","desc":""},"relativePath":"202004/20200320 Control the firewall at the command line.md","filePath":"[post].md"}'),g={name:"202004/20200320 Control the firewall at the command line.md"};function u(f,s,k,h,b,m){const t=r("Link");return d(),p("div",null,[s[37]||(s[37]=l('<h1 id="在-fedora-命令列下玩轉防火牆" tabindex="-1">在 Fedora 命令列下玩轉防火牆 <a class="header-anchor" href="#在-fedora-命令列下玩轉防火牆" aria-label="Permalink to “在 Fedora 命令列下玩轉防火牆”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202004/12/123040ghxuicphyhsoppch.jpg" alt=""></p><p>網絡防火牆，顧名思義：為了阻止不需要的網絡連接而設置的防護性屏障。在與外界建立連接或是提供網絡服務時常常會用到。例如，在學校或是咖啡廳裏使用筆記本電腦時，你一定不想某個陌生人窺探你的電腦。</p><p>每個 Fedora 系統都內置了一款防火牆。這是 Linux 內核網絡功能的一部分。本文介紹如何通過 <code>firewall-cmd</code> 命令修改防火牆的配置。</p><h3 id="網絡基礎" tabindex="-1">網絡基礎 <a class="header-anchor" href="#網絡基礎" aria-label="Permalink to “網絡基礎”">​</a></h3>',5)),i("p",null,[s[1]||(s[1]=e("本文並不教授計算機網絡的",-1)),a(t,{href:"https://en.wikipedia.org/wiki/Portal:Internet"},{default:n(()=>[...s[0]||(s[0]=[e("所有知識",-1)])]),_:1}),s[2]||(s[2]=e("，但還是會簡單介紹一些網絡基礎。",-1))]),s[38]||(s[38]=i("p",null,[e("網絡中的所有計算機都有一個 "),i("em",null,"IP 地址"),e("，可以把它想像成一個郵箱地址，有了郵箱地址，郵件才知道發往何處。每台計算機還會擁有一組"),i("em",null,"端口"),e("，端口號範圍從 0 到 65535。同樣的，你可以把這些端口想像成用來連接郵箱地址的連接點。")],-1)),s[39]||(s[39]=i("p",null,"通常情況下，端口會是一個標準端口號或是根據應用程序的應答要求選定的一個端口範圍。例如，一台 Web 服務器通常會保留 80 端口用於 HTTP 通信，443 端口用於 HTTPS。小於 1024 的端口主要用於系統或常見用途，1024-49151 端口是已經註冊的，49152 及以上端口多為臨時使用（只限短時間使用）。",-1)),i("p",null,[s[5]||(s[5]=e("互聯網傳輸中最常見的兩個協議，",-1)),a(t,{href:"https://en.wikipedia.org/wiki/Transmission_Control_Protocol"},{default:n(()=>[...s[3]||(s[3]=[e("TCP",-1)])]),_:1}),s[6]||(s[6]=e(" 和 ",-1)),a(t,{href:"https://en.wikipedia.org/wiki/User_Datagram_Protocol"},{default:n(()=>[...s[4]||(s[4]=[e("UDP",-1)])]),_:1}),s[7]||(s[7]=e("。當要傳輸的數據很重要，不能有丟包時，就使用 TCP 協議，如果數據包沒有按順序到達，還需要重組為正確的順序。UDP 協議則更多用於對時間敏感的服務，為了保證時效性，有時允許丟失部分數據。",-1))]),s[40]||(s[40]=i("p",null,"系統中運行的應用，例如 Web 服務器，會保留一些端口（例如上文提到的 80 和 443）。在網絡傳輸過程中，主機會為傳輸的兩端建立一個鏈接，一端是源地址和源端口，另一端是目的地址和目的端口。",-1)),s[41]||(s[41]=i("p",null,[e("網絡防火牆就是基於地址、端口及其他標準的一組規則集，來對網絡數據的傳輸進行屏蔽或阻斷的。通過 "),i("code",null,"firewall-cmd"),e(" 命令，我們就可以查看或修改防火牆的工作配置。")],-1)),s[42]||(s[42]=i("h3",{id:"防火牆域-zone",tabindex:"-1"},[e("防火牆域（zone） "),i("a",{class:"header-anchor",href:"#防火牆域-zone","aria-label":"Permalink to “防火牆域（zone）”"},"​")],-1)),i("p",null,[s[10]||(s[10]=e("為了驗證防火牆是否開啓，使用 ",-1)),s[11]||(s[11]=i("code",null,"firewall-cmd",-1)),s[12]||(s[12]=e(" 命令，輸入時要加上 ",-1)),a(t,{href:"https://fedoramagazine.org/howto-use-sudo/"},{default:n(()=>[...s[8]||(s[8]=[e("sudo",-1)])]),_:1}),s[13]||(s[13]=e("。（通常，在運行了 ",-1)),a(t,{href:"https://en.wikipedia.org/wiki/Polkit"},{default:n(()=>[...s[9]||(s[9]=[e("PolicyKit",-1)])]),_:1}),s[14]||(s[14]=e(" 的環境中，你也可以不加 ",-1)),s[15]||(s[15]=i("code",null,"sudo",-1)),s[16]||(s[16]=e("）",-1))]),s[43]||(s[43]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --state</span></span>
<span class="line"><span>running</span></span></code></pre></div><p>firewalld 服務支持任意數量的域。每個域都可以擁有獨立的配置和防護規則。一台 Fedora 工作站的外部接口（例如 WIFI 或有線網卡）其默認域為 <code>FedoraWorkstation</code>。</p><p>要看有哪些域是激活狀態，可以使用 <code>-–get-active-zones</code> 選項。在本示例中，有兩個網卡，有線以太網卡 <code>wlp2s0</code> 和虛擬（libvirt）橋接網卡 <code>virbr0</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --get-active-zones</span></span>
<span class="line"><span>FedoraWorkstation</span></span>
<span class="line"><span>  interfaces: wlp2s0</span></span>
<span class="line"><span>libvirt</span></span>
<span class="line"><span>  interfaces: virbr0</span></span></code></pre></div><p>如果想看看默認域是什麼，或是直接查詢所有域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --get-default-zone</span></span>
<span class="line"><span>FedoraWorkstation</span></span>
<span class="line"><span>$ sudo firewall-cmd --get-zones</span></span>
<span class="line"><span>FedoraServer FedoraWorkstation block dmz drop external home internal libvirt public trusted work</span></span></code></pre></div><p>查詢默認域中防火牆放行了哪些系統，使用 <code>-–list-services</code> 選項。下例給出了一個定製系統的查詢結果，你可以看到與常見的結果有些不同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --list-services</span></span>
<span class="line"><span>dhcpv6-client mdns samba-client ssh</span></span></code></pre></div><p>該系統對外開啓了四個服務。每個服務都對應一個常見端口。例如 <code>ssh</code> 服務對應 22 端口。</p><p>如果要查看當前域中防火牆還開啓了哪些端口，可以使用 <code>--list-ports</code> 選項。當然，你也可以隨時對其他域進行查詢：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --list-ports --zone=FedoraWorkstation</span></span>
<span class="line"><span>1025-65535/udp 1025-65535/tcp</span></span></code></pre></div><p>結果表明，從 1025 到 65535 端口（包含 UDP 和 TCP）默認都是開啓的。</p><h3 id="修改域、端口及服務" tabindex="-1">修改域、端口及服務 <a class="header-anchor" href="#修改域、端口及服務" aria-label="Permalink to “修改域、端口及服務”">​</a></h3><p>以上的配置都是預先設計好的防火牆策略。是為了確保新手用户安裝的應用都能夠正常訪問網絡。如果你確定自己心裏有數，想要一個保護性更強的策略，可以將接口放入 <code>FedoraServer</code> 域，明確禁止所有端口的訪問。（<strong>警告</strong>：如果你的服務器之前是聯網狀態，這麼做可能會導致連接中斷，那你就得到機房裏去修改更多的配置項！）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --change-interface=&lt;ifname&gt; --zone=FedoraServer</span></span>
<span class="line"><span>success</span></span></code></pre></div><p><strong>本文並不討論如何制定防火牆策略，Fedora 社區裏已經有很多討論了。你大可以按照自身需要來修改配置。</strong></p><p>如果你想要開放某個服務的常見端口，可以將該服務加入默認域（或使用 <code>--zone</code> 指定一個不同的域）。還可以一次性將其加入多個域。下例開放了 HTTP 和 HTTPS 的常見端口 80、443：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-service=http --add-service=https</span></span>
<span class="line"><span>success</span></span></code></pre></div><p>並非所有的服務都有默認端口，不過大部分都是有的。使用 <code>-–get-services</code> 選項可以查看完整列表。</p><p>如果你想指定某個特定端口號，可以直接用數字和協議進行配置。（多數情況下，<code>-–add-service</code> 和 <code>-–add-port</code> 這兩個選項是合在一起使用的）下例開啓的是 UDP 協議的網絡啓動服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-port=67/udp</span></span>
<span class="line"><span>success</span></span></code></pre></div><p><strong>重要</strong>：如果想要在系統重啓或是 firewalld 服務重啓後，配置仍然生效，<strong>必須</strong>在命令中加上 <code>-–permanent</code> 選項。本文中的例子只是臨時修改了配置，下次遇到系統重啓或是 firewalld 服務重啓，這些配置就失效了。</p>`,22)),i("p",null,[s[18]||(s[18]=e("以上只是 ",-1)),s[19]||(s[19]=i("code",null,"firewall-cmd",-1)),s[20]||(s[20]=e(" 和 firewalld 服務諸多功能中的一小部分。firewalld 項目的",-1)),a(t,{href:"https://firewalld.org/"},{default:n(()=>[...s[17]||(s[17]=[e("主頁",-1)])]),_:1}),s[21]||(s[21]=e("還有更多信息值得你去探索和嘗試。",-1))]),s[44]||(s[44]=i("hr",null,null,-1)),i("p",null,[s[23]||(s[23]=e("via: ",-1)),a(t,{href:"https://fedoramagazine.org/control-the-firewall-at-the-command-line/"},{default:n(()=>[...s[22]||(s[22]=[e("https://fedoramagazine.org/control-the-firewall-at-the-command-line/",-1)])]),_:1})]),i("p",null,[s[28]||(s[28]=e("作者：",-1)),a(t,{href:"https://fedoramagazine.org/author/pfrields/"},{default:n(()=>[...s[24]||(s[24]=[e("Paul W. Frields",-1)])]),_:1}),s[29]||(s[29]=e(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[25]||(s[25]=[e("lujun9972",-1)])]),_:1}),s[30]||(s[30]=e(" 譯者：",-1)),a(t,{href:"https://github.com/tinyeyeser"},{default:n(()=>[...s[26]||(s[26]=[e("tinyeyeser",-1)])]),_:1}),s[31]||(s[31]=e(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:n(()=>[...s[27]||(s[27]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[34]||(s[34]=e("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[32]||(s[32]=[e("LCTT",-1)])]),_:1}),s[35]||(s[35]=e(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:n(()=>[...s[33]||(s[33]=[e("Linux中國",-1)])]),_:1}),s[36]||(s[36]=e(" 榮譽推出",-1))])])}const v=o(g,[["render",u]]);export{T as __pageData,v as default};
